INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4196446, 604387, 76430, '<td valign="top">This is a great shot.  The picture frame of the burned doorway with the burning outside and burned inside of the home makes this one of the best and probably the riskiest picture of the challenge.  How on earth did you get this?  I have an entry, and I''m not voting, but I would rate this highest of the challenge that I''ve seen so far.  And to think I was only a couple of miles from this.</td>', 'This is a great shot.  The picture frame of the burned doorway with the burning outside and burned inside of the home makes this one of the best and probably the riskiest picture of the challenge.  How on earth did you get this?  I have an entry, and I''m not voting, but I would rate this highest of the challenge that I''ve seen so far.  And to think I was only a couple of miles from this.', '2007-10-26 01:13:30.000000', NULL, 1),
(4196452, 604779, 76430, '<td valign="top">LOL, great caption!  Is this really a lemon?  A little diffusion on the flash would have been good.</td>', 'LOL, great caption!  Is this really a lemon?  A little diffusion on the flash would have been good.', '2007-10-26 01:15:05.000000', NULL, 1),
(4196455, 602508, 69776, '<td valign="top">Nice in BW but might be too a bit too far away for me</td>', 'Nice in BW but might be too a bit too far away for me', '2007-10-26 01:15:52.000000', NULL, 1),
(4196460, 602482, 69776, '<td valign="top">Hmmm looks like a bit of a shoe horn for me, its a nice enough photo but lacks a bit of contrast, did you shoot through glass for this?</td>', 'Hmmm looks like a bit of a shoe horn for me, its a nice enough photo but lacks a bit of contrast, did you shoot through glass for this?', '2007-10-26 01:17:00.000000', NULL, 1),
(4196463, 602907, 69776, '<td valign="top">Great emotion captured with the girl clasping her ears. Good Dof but as a headlining story in the paper, I would expect to see faces.</td>', 'Great emotion captured with the girl clasping her ears. Good Dof but as a headlining story in the paper, I would expect to see faces.', '2007-10-26 01:18:00.000000', NULL, 1),
(4196464, 602823, 69776, '<td valign="top">Nice image but too many faces not looking this way. the BW works well</td>', 'Nice image but too many faces not looking this way. the BW works well', '2007-10-26 01:18:35.000000', NULL, 1),
(4196466, 603847, 76430, '<td valign="top">Very lovely fall scene with good thirds composition on the water and hilltop.  I''d like to see the whole hillside illuminated in sunlight.  With the layer of clouds showing that may not have been possible.</td>', 'Very lovely fall scene with good thirds composition on the water and hilltop.  I''d like to see the whole hillside illuminated in sunlight.  With the layer of clouds showing that may not have been possible.', '2007-10-26 01:19:22.000000', NULL, 1),
(4196468, 602508, 5705, '<td valign="top">very real shot-- well done</td>', 'very real shot-- well done', '2007-10-26 01:20:12.000000', NULL, 1),
(4196469, 604094, 69776, '<td valign="top">colours look washed out to me and the fish eye distortion prob wouldn''t go to well on the cover.  The connection to the challenge is in your title not the photo.  However as a photo I quite like it and under basic editing it would look great</td>', 'colours look washed out to me and the fish eye distortion prob wouldn''t go to well on the cover.  The connection to the challenge is in your title not the photo.  However as a photo I quite like it and under basic editing it would look great', '2007-10-26 01:20:16.000000', NULL, 1),
(4196472, 604357, 76430, '<td valign="top">Use the 640 pixels given to you.  Here in Southern California this isn''t big news, but I assume you''re further north.</td>', 'Use the 640 pixels given to you.  Here in Southern California this isn''t big news, but I assume you''re further north.', '2007-10-26 01:20:35.000000', NULL, 1),
(4196475, 603787, 5705, '<td valign="top">yep 10--</td>', 'yep 10--', '2007-10-26 01:20:41.000000', NULL, 1),
(4196476, 604824, 76430, '<td valign="top">Good DOF and non-facial emotional expression.</td>', 'Good DOF and non-facial emotional expression.', '2007-10-26 01:21:30.000000', NULL, 1),
(4196477, 604369, 69776, '<td valign="top">Nice humor, the BW doesn''t work well for me, but the colours may have been bad.  the centered comp is a bit plain, but perhaps it would work as a story</td>', 'Nice humor, the BW doesn''t work well for me, but the colours may have been bad.  the centered comp is a bit plain, but perhaps it would work as a story', '2007-10-26 01:21:51.000000', NULL, 1),
(4196478, 604387, 5705, '<td valign="top">great framing-- 10</td>', 'great framing-- 10', '2007-10-26 01:21:58.000000', NULL, 1),
(4196480, 603355, 50641, '<td valign="top">Heh.</td>', 'Heh.', '2007-10-26 01:23:09.000000', NULL, 1),
(4196483, 604692, 5705, '<td valign="top">Freaking sweet!  I dont know if a homeless person would have such a nice wheelchair though?</td>', 'Freaking sweet!  I dont know if a homeless person would have such a nice wheelchair though?', '2007-10-26 01:23:45.000000', NULL, 1),
(4196484, 604387, 50641, '<td valign="top">excellent framing.</td>', 'excellent framing.', '2007-10-26 01:23:47.000000', NULL, 1),
(4196487, 604742, 76430, '<td valign="top">I love this shot.  Excellent close composition and expression.  She doesn''t physically look famished, but more of a model, though it does bring the emotion and point across.</td>', 'I love this shot.  Excellent close composition and expression.  She doesn''t physically look famished, but more of a model, though it does bring the emotion and point across.', '2007-10-26 01:24:31.000000', NULL, 1),
(4196489, 604173, 15711, '<td valign="top">Great image but doesn''t look really photojournalistic to me.  I guess I think more of "out on the street" kind of shot that tells me exactly what is the story, without me having to read the title. Having said that, this is great and I like the focus, lighting and composition.</td>', 'Great image but doesn''t look really photojournalistic to me.  I guess I think more of "out on the street" kind of shot that tells me exactly what is the story, without me having to read the title. Having said that, this is great and I like the focus, lighting and composition.', '2007-10-26 01:24:39.000000', NULL, 1),
(4196490, 604779, 50641, '<td valign="top">haha ;-)</td>', 'haha ;-)', '2007-10-26 01:24:40.000000', NULL, 1),
(4196492, 603294, 5885, '<td valign="top">Nive shot and nice headline</td>', 'Nive shot and nice headline', '2007-10-26 01:25:40.000000', NULL, 1),
(4196493, 604449, 5705, '<td valign="top">better than the shots I see on my local sports page that have been edited!!  10 from me</td>', 'better than the shots I see on my local sports page that have been edited!!  10 from me', '2007-10-26 01:25:40.000000', NULL, 1),
(4196496, 604369, 15711, '<td valign="top">That is pretty darn funny.  I wish more of her legs and feet were included in the shot.  Doesn''t minimal editing suck?  With contrast and levels adjustments, this could be kickin''.</td>', 'That is pretty darn funny.  I wish more of her legs and feet were included in the shot.  Doesn''t minimal editing suck?  With contrast and levels adjustments, this could be kickin''.', '2007-10-26 01:26:38.000000', NULL, 1),
(4196497, 603787, 23394, '<td valign="top">can''t believe you''d stoop to arson, just to have an entry ;-)</td>', 'can''t believe you''d stoop to arson, just to have an entry ;-)', '2007-10-26 01:26:40.000000', NULL, 1),
(4196500, 602409, 5705, '<td valign="top">I love it! 10</td>', 'I love it! 10', '2007-10-26 01:27:53.000000', NULL, 1),
(4196501, 603294, 23394, '<td valign="top">nice work (as usual), but you''ll probably get hammered as a sports shot is not typically ''front page'' news...good luck!</td>', 'nice work (as usual), but you''ll probably get hammered as a sports shot is not typically ''front page'' news...good luck!', '2007-10-26 01:27:57.000000', NULL, 1),
