(4196506, 604150, 23394, '<td valign="top">nice portrait, but not really seeing anything story-telling here.</td>', 'nice portrait, but not really seeing anything story-telling here.', '2007-10-26 01:29:06.000000', NULL, 1),
(4196508, 602823, 23394, '<td valign="top">nice image, but not really seeing a story here.</td>', 'nice image, but not really seeing a story here.', '2007-10-26 01:30:01.000000', NULL, 1),
