(4196514, 604824, 5705, '<td valign="top">Good emotion-- 9</td>', 'Good emotion-- 9', '2007-10-26 01:31:28.000000', NULL, 1),
(4196515, 604140, 23394, '<td valign="top">nice enough shot, but not really story-telling.  (fwiw, i use q-tips a couple times a week; works wonders...)</td>', 'nice enough shot, but not really story-telling.  (fwiw, i use q-tips a couple times a week; works wonders...)', '2007-10-26 01:32:11.000000', NULL, 1),
(4196518, 604606, 23394, '<td valign="top">pretty, pretty picture, but dnmc ;-)</td>', 'pretty, pretty picture, but dnmc ;-)', '2007-10-26 01:32:42.000000', NULL, 1),
(4196519, 604798, 67237, '<td valign="top">good focus. Not crazy about composition and exposure. The photo does not add to the interest of the theme.</td>', 'good focus. Not crazy about composition and exposure. The photo does not add to the interest of the theme.', '2007-10-26 01:32:42.000000', NULL, 1),
