(4196873, 604698, 47906, '<td valign="top">Very interesting subject, good job positioning the ambulance door on the left 3rd of the frame</td>', 'Very interesting subject, good job positioning the ambulance door on the left 3rd of the frame', '2007-10-26 08:17:12.000000', NULL, 1),
(4196874, 603875, 47906, '<td valign="top">Nice diagonal created by the soldiers. Nice and sharp.</td>', 'Nice diagonal created by the soldiers. Nice and sharp.', '2007-10-26 08:17:48.000000', NULL, 1),
(4196875, 604781, 47906, '<td valign="top">Great capture, very photojournalistic. Like the slight blur of the trolley</td>', 'Great capture, very photojournalistic. Like the slight blur of the trolley', '2007-10-26 08:18:49.000000', NULL, 1),
(4196877, 604481, 47906, '<td valign="top">Good group shot, the skin seems to have a reddish tint to it how ever. But it is great how much happiness is conveyed in this shot.</td>', 'Good group shot, the skin seems to have a reddish tint to it how ever. But it is great how much happiness is conveyed in this shot.', '2007-10-26 08:19:45.000000', NULL, 1),
(4196878, 602907, 47906, '<td valign="top">Great postioning of your foreground and background subjects. Excellent shot.</td>', 'Great postioning of your foreground and background subjects. Excellent shot.', '2007-10-26 08:20:25.000000', NULL, 1),
(4196879, 604094, 47906, '<td valign="top">Cool Shot, Very symmetric. Nice fisheye?</td>', 'Cool Shot, Very symmetric. Nice fisheye?', '2007-10-26 08:20:53.000000', NULL, 1),
(4196880, 602409, 47906, '<td valign="top">Good action felt through out this shot, really fun.</td>', 'Good action felt through out this shot, really fun.', '2007-10-26 08:21:38.000000', NULL, 1),
(4196882, 604593, 47906, '<td valign="top">Wow thats alot of garbage, whats the story behind it?  Nice leading lines in the shot. gives alot of depth to the photo.</td>', 'Wow thats alot of garbage, whats the story behind it?  Nice leading lines in the shot. gives alot of depth to the photo.', '2007-10-26 08:22:47.000000', NULL, 1),
(4196883, 602697, 47906, '<td valign="top">Good Detail on the rocks.</td>', 'Good Detail on the rocks.', '2007-10-26 08:23:17.000000', NULL, 1),
(4196884, 604542, 47906, '<td valign="top">Wow this is tragic, I truely hope everyone was ok.</td>', 'Wow this is tragic, I truely hope everyone was ok.', '2007-10-26 08:24:09.000000', NULL, 1),
(4196885, 602352, 47906, '<td valign="top">Great portrait, He fits what I truely imagine when I think of one too.</td>', 'Great portrait, He fits what I truely imagine when I think of one too.', '2007-10-26 08:24:49.000000', NULL, 1),
(4196886, 603294, 47906, '<td valign="top">Great Sports action photo</td>', 'Great Sports action photo', '2007-10-26 08:25:08.000000', NULL, 1),
(4196889, 602755, 47906, '<td valign="top">Neat shot, this has alot of detail and texture to it. It is really interesting.</td>', 'Neat shot, this has alot of detail and texture to it. It is really interesting.', '2007-10-26 08:25:39.000000', NULL, 1),
(4196890, 602973, 47906, '<td valign="top">Very simple and well shot, elegant.</td>', 'Very simple and well shot, elegant.', '2007-10-26 08:26:01.000000', NULL, 1),
(4196891, 604816, 47906, '<td valign="top">Feels a bit soft to me, and the horizon is a bit tilted. The colors are nice and the leading lines created by the players are good also.</td>', 'Feels a bit soft to me, and the horizon is a bit tilted. The colors are nice and the leading lines created by the players are good also.', '2007-10-26 08:27:12.000000', NULL, 1),
