INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4196894, 604692, 47906, '<td valign="top">Great capture and postioning in the frame, a photo that really gives homelessness the thought it deserves. Nice shot.</td>', 'Great capture and postioning in the frame, a photo that really gives homelessness the thought it deserves. Nice shot.', '2007-10-26 08:28:41.000000', NULL, 1),
(4196895, 604568, 47906, '<td valign="top">Your horizon is slightly tilted, the colors are nice and the DOF used compliments the photo well.</td>', 'Your horizon is slightly tilted, the colors are nice and the DOF used compliments the photo well.', '2007-10-26 08:29:30.000000', NULL, 1),
(4196897, 603345, 47906, '<td valign="top">Good capture of things that happen in big cities on a day to day basis</td>', 'Good capture of things that happen in big cities on a day to day basis', '2007-10-26 08:31:00.000000', NULL, 1),
(4196898, 602756, 47906, '<td valign="top">Great shot, very sharp and detailed.</td>', 'Great shot, very sharp and detailed.', '2007-10-26 08:31:30.000000', NULL, 1),
(4196899, 604551, 47906, '<td valign="top">Really great action caputre.</td>', 'Really great action caputre.', '2007-10-26 08:31:52.000000', NULL, 1),
(4196900, 604158, 47906, '<td valign="top">Beautiful capture and DOF used on this entry. Nice colors</td>', 'Beautiful capture and DOF used on this entry. Nice colors', '2007-10-26 08:32:21.000000', NULL, 1),
(4196901, 604051, 47906, '<td valign="top">Nice composition and symmetry in the photo</td>', 'Nice composition and symmetry in the photo', '2007-10-26 08:32:54.000000', NULL, 1),
(4196902, 604798, 47906, '<td valign="top">Nice DOF in this shot, very good composition and framing.</td>', 'Nice DOF in this shot, very good composition and framing.', '2007-10-26 08:33:32.000000', NULL, 1),
(4196904, 604710, 47906, '<td valign="top">Very funny shot, Love it.</td>', 'Very funny shot, Love it.', '2007-10-26 08:33:56.000000', NULL, 1),
(4196906, 604779, 47906, '<td valign="top">Wow that thing is ugly looking, what is it? Very good idea for the challenge, nice colors and sharpness.</td>', 'Wow that thing is ugly looking, what is it? Very good idea for the challenge, nice colors and sharpness.', '2007-10-26 08:34:42.000000', NULL, 1),
(4196907, 604575, 47906, '<td valign="top">Very nice moody image, I like the silohuetteing of the model in the door way</td>', 'Very nice moody image, I like the silohuetteing of the model in the door way', '2007-10-26 08:35:14.000000', NULL, 1),
(4196908, 602939, 67152, '<td valign="top">This is a splendid image - really cries out for a cover</td>', 'This is a splendid image - really cries out for a cover', '2007-10-26 08:35:31.000000', NULL, 1),
(4196911, 604387, 55956, '<td valign="top">this is a great image.</td>', 'this is a great image.', '2007-10-26 08:37:28.000000', NULL, 1),
(4196915, 603787, 67152, '<td valign="top">excellent image - this should be on a cover</td>', 'excellent image - this should be on a cover', '2007-10-26 08:39:29.000000', NULL, 1),
(4196917, 604395, 67152, '<td valign="top">the joy displayed in this photo - looks like a magazine cover for sure!</td>', 'the joy displayed in this photo - looks like a magazine cover for sure!', '2007-10-26 08:39:50.000000', NULL, 1),
(4196918, 602756, 67152, '<td valign="top">really nice details and contrast - really solid image</td>', 'really nice details and contrast - really solid image', '2007-10-26 08:40:04.000000', NULL, 1),
(4196919, 604094, 67152, '<td valign="top">love the distorted perspective to provide a great metaphor for the ''story''</td>', 'love the distorted perspective to provide a great metaphor for the ''story''', '2007-10-26 08:40:28.000000', NULL, 1),
(4196921, 604150, 67152, '<td valign="top">fantastic portrait - i can really see this image on a cover - really jumps off the page</td>', 'fantastic portrait - i can really see this image on a cover - really jumps off the page', '2007-10-26 08:40:51.000000', NULL, 1),
(4196932, 604357, 67152, '<td valign="top">the image seems oversharpened, the background is distracting, and I really don''t see this on a newspaper or other news magazine</td>', 'the image seems oversharpened, the background is distracting, and I really don''t see this on a newspaper or other news magazine', '2007-10-26 08:47:31.000000', NULL, 1),
(4196939, 604549, 75034, '<td valign="top">This is a nice human interest photo. I like capture on the falling dirt, The expression on his face tells the story for us. With this shot B&amp;W works very well, your subject appears to jump out at you. Overall this shot is well consived and set up. It is hard to get good lighting in a challenge with such limited editing rules, but that is not a problem here, you were patient and waited by the look of things. I doubt that I''ll see another approach that is similar to this one.</td>', 'This is a nice human interest photo. I like capture on the falling dirt, The expression on his face tells the story for us. With this shot B&W works very well, your subject appears to jump out at you. Overall this shot is well consived and set up. It is hard to get good lighting in a challenge with such limited editing rules, but that is not a problem here, you were patient and waited by the look of things. I doubt that I''ll see another approach that is similar to this one.', '2007-10-26 08:51:46.000000', NULL, 1),
(4196945, 602377, 67258, '<td valign="top">A good clean shot, with pleasing light and contrast.  Good choice of depth of field, and perfect timing.  I could see  this accompanying an article in a regional paper - although perhaps not front page material.</td>', 'A good clean shot, with pleasing light and contrast.  Good choice of depth of field, and perfect timing.  I could see  this accompanying an article in a regional paper - although perhaps not front page material.', '2007-10-26 08:54:25.000000', NULL, 1),
(4196950, 604369, 70661, '<td valign="top">Love it! 10</td>', 'Love it! 10', '2007-10-26 08:56:13.000000', NULL, 1),
(4196956, 603787, 43774, '<td valign="top">Well I believe we have a winner.</td>', 'Well I believe we have a winner.', '2007-10-26 08:57:51.000000', NULL, 1),
(4196957, 604474, 67258, '<td valign="top">The School Bus(?) adds the emotive factor to the scene.  The scene is perhaps a bit too cluttered and because of this, for me, loses some of its impact.  I wonder if a stronger composition would be possible by zooming in so that just the front of the bus, the fire truck and the ''arrested'' man and officers were in the frame?</td>', 'The School Bus(?) adds the emotive factor to the scene.  The scene is perhaps a bit too cluttered and because of this, for me, loses some of its impact.  I wonder if a stronger composition would be possible by zooming in so that just the front of the bus, the fire truck and the ''arrested'' man and officers were in the frame?', '2007-10-26 08:58:14.000000', NULL, 1),
(4196960, 602973, 67258, '<td valign="top">I am afraid I don''t know who JW was...<br/>I couldn''t really see this photo accompanying a news article, and I struggle to realy get a connection with the challenge.  As a stand alone photo it seems a luittle flat and I get a feeling of accidental composition.</td>', 'I am afraid I don''t know who JW was...I couldn''t really see this photo accompanying a news article, and I struggle to realy get a connection with the challenge.  As a stand alone photo it seems a luittle flat and I get a feeling of accidental composition.', '2007-10-26 09:00:38.000000', NULL, 1),
(4196964, 604369, 28532, '<td valign="top">This just cracks me up!!  Love it!!</td>', 'This just cracks me up!!  Love it!!', '2007-10-26 09:01:45.000000', NULL, 1),
(4196968, 604542, 67258, '<td valign="top">Meets tha challenge, but not a photo that really holds my attention</td>', 'Meets tha challenge, but not a photo that really holds my attention', '2007-10-26 09:02:39.000000', NULL, 1),
(4196973, 602482, 67258, '<td valign="top">Along with many others in this challenge, this seems to be a bit of a shoe-horn in.  That said, given Minimal editing, you have got a well composed urban landscape with some good depth.</td>', 'Along with many others in this challenge, this seems to be a bit of a shoe-horn in.  That said, given Minimal editing, you have got a well composed urban landscape with some good depth.', '2007-10-26 09:04:55.000000', NULL, 1),
(4196978, 602697, 67258, '<td valign="top">Along with many others in this challenge, this seems to be a bit of a shoe-horn in, but perhaps papers in other parts of the world publish different stories and pictures to those I read. The photo itself is well composed, but I find the heavy colour-caste off-putting.</td>', 'Along with many others in this challenge, this seems to be a bit of a shoe-horn in, but perhaps papers in other parts of the world publish different stories and pictures to those I read. The photo itself is well composed, but I find the heavy colour-caste off-putting.', '2007-10-26 09:06:13.000000', NULL, 1),
(4196981, 604369, 67258, '<td valign="top">Hee, I like it!Well composed, although I might prefer batman tio be standing a little forward of the wall and staircase.  The B&amp;W tonal range is a little on the dark side - for minimal editing I wonder if it would have been stronger photographed in colour?</td>', 'Hee, I like it!Well composed, although I might prefer batman tio be standing a little forward of the wall and staircase.  The B&W tonal range is a little on the dark side - for minimal editing I wonder if it would have been stronger photographed in colour?', '2007-10-26 09:08:01.000000', NULL, 1),
(4196985, 604173, 61552, '<td valign="top">This concentrates on the face.  Good pic, but I think the front page title and pic should concentrate more on the entire outfit.  Still good pic.</td>', 'This concentrates on the face.  Good pic, but I think the front page title and pic should concentrate more on the entire outfit.  Still good pic.', '2007-10-26 09:11:28.000000', NULL, 1),
(4196987, 604140, 61552, '<td valign="top">Needs a better front page title like "Stars Flight Returns With Body Of Lost Hiker"</td>', 'Needs a better front page title like "Stars Flight Returns With Body Of Lost Hiker"', '2007-10-26 09:13:13.000000', NULL, 1),
(4197022, 604487, 74975, '<td valign="top">Um... Isn''t this photo in the challenge twice?</td>', 'Um... Isn''t this photo in the challenge twice?', '2007-10-26 09:53:33.000000', NULL, 1),
(4197037, 604358, 81301, '<td valign="top">you are the blue!!!</td>', 'you are the blue!!!', '2007-10-26 10:06:01.000000', NULL, 1),
(4197043, 602754, 67152, '<td valign="top">An interesting twist on a news story - but the image itself is a bit difficult to discern - probably due to too much water in the foreground</td>', 'An interesting twist on a news story - but the image itself is a bit difficult to discern - probably due to too much water in the foreground', '2007-10-26 10:11:40.000000', NULL, 1),
(4197044, 604094, 80904, '<td valign="top">I Like this shot, it does help you that I am a fan of wide angle lenses. ;)<br/>Nicely done with the symetry. 9</td>', 'I Like this shot, it does help you that I am a fan of wide angle lenses. ;)Nicely done with the symetry. 9', '2007-10-26 10:14:46.000000', NULL, 1),
(4197048, 604369, 80904, '<td valign="top">Now this took some work. Good shot, nice creativity and I bet it took some effort to set this up. (it also helps its close to halloween)</td>', 'Now this took some work. Good shot, nice creativity and I bet it took some effort to set this up. (it also helps its close to halloween)', '2007-10-26 10:17:38.000000', NULL, 1),
(4197076, 604542, 61552, '<td valign="top">Would have ben a stronger impact with a crying baby on the chair!</td>', 'Would have ben a stronger impact with a crying baby on the chair!', '2007-10-26 10:34:57.000000', NULL, 1),
(4197092, 604140, 5822, '<td valign="top">Technically excellent, but as a photojournalistic shot I would have liked to see who is being rescued. I really like the fire-engine red against the cool mountain colors.</td>', 'Technically excellent, but as a photojournalistic shot I would have liked to see who is being rescued. I really like the fire-engine red against the cool mountain colors.', '2007-10-26 10:41:24.000000', NULL, 1),
(4197095, 602756, 61552, '<td valign="top">HAHA!  Where''s the donut shop?</td>', 'HAHA!  Where''s the donut shop?', '2007-10-26 10:41:55.000000', NULL, 1),
(4197101, 604812, 61552, '<td valign="top">Great title!</td>', 'Great title!', '2007-10-26 10:43:45.000000', NULL, 1),
(4197110, 603875, 61552, '<td valign="top">I hope not.  Good shot.</td>', 'I hope not.  Good shot.', '2007-10-26 10:46:08.000000', NULL, 1),
(4197155, 604606, 5822, '<td valign="top">Beautiful capture and I can definitely see this illustrating a story in the magazine you''ve chosen.</td>', 'Beautiful capture and I can definitely see this illustrating a story in the magazine you''ve chosen.', '2007-10-26 11:00:52.000000', NULL, 1),
(4197156, 602352, 33672, '<td valign="top">Great job! Nice Control of DOF and B&amp;W conversion works well.</td>', 'Great job! Nice Control of DOF and B&W conversion works well.', '2007-10-26 11:01:09.000000', NULL, 1),
(4197157, 604831, 15711, '<td valign="top">This is probably the most impactful shot of the challenge.  I wish they''d allowed advanced editing - it could have really given it some PUNCH. Sad, the story this tells, which is what photojournalism is all about. 8</td>', 'This is probably the most impactful shot of the challenge.  I wish they''d allowed advanced editing - it could have really given it some PUNCH. Sad, the story this tells, which is what photojournalism is all about. 8', '2007-10-26 11:01:18.000000', NULL, 1),
(4197161, 604369, 11854, '<td valign="top">ROFLMAO!</td>', 'ROFLMAO!', '2007-10-26 11:02:18.000000', NULL, 1),
(4197169, 604387, 11854, '<td valign="top">Excellent job! Scary and emotional. 10</td>', 'Excellent job! Scary and emotional. 10', '2007-10-26 11:07:54.000000', NULL, 1),
(4197173, 604487, 11854, '<td valign="top">Nicely done, great detail. 10</td>', 'Nicely done, great detail. 10', '2007-10-26 11:09:05.000000', NULL, 1),
(4197181, 604369, 5822, '<td valign="top">lol....lol....lol<br/>Sorry, couldn''t help it. I guess this would be top story in a comic book. 7</td>', 'lol....lol....lolSorry, couldn''t help it. I guess this would be top story in a comic book. 7', '2007-10-26 11:12:19.000000', NULL, 1),
(4197209, 604816, 33672, '<td valign="top">Great seats, tough light (especially in minimal editing...)</td>', 'Great seats, tough light (especially in minimal editing...)', '2007-10-26 11:22:15.000000', NULL, 1),
(4197210, 604548, 33672, '<td valign="top">Nice colors!</td>', 'Nice colors!', '2007-10-26 11:22:39.000000', NULL, 1),
(4197219, 604568, 33672, '<td valign="top">I love this city! PHoto seems a bit overexposed, however. turn it down a stop or two.</td>', 'I love this city! PHoto seems a bit overexposed, however. turn it down a stop or two.', '2007-10-26 11:24:27.000000', NULL, 1),
(4197240, 604150, 74979, '<td valign="top">quite nice in its simplicity!  love the POV &amp; composition...7</td>', 'quite nice in its simplicity!  love the POV & composition...7', '2007-10-26 11:31:16.000000', NULL, 1),
(4197253, 604816, 29797, '<td valign="top">...and on Miami''s turf too! Go Pats!!! Nice shot, looks like your seats were just about right on the 50 and at a perfect level. You can really feel the intensity looking down the line of scrimmage here.</td>', '...and on Miami''s turf too! Go Pats!!! Nice shot, looks like your seats were just about right on the 50 and at a perfect level. You can really feel the intensity looking down the line of scrimmage here.', '2007-10-26 11:36:17.000000', NULL, 1),
(4197255, 604354, 5822, '<td valign="top">Nice POV but I don''t think it has the impact to be illustrating a front cover story.</td>', 'Nice POV but I don''t think it has the impact to be illustrating a front cover story.', '2007-10-26 11:36:30.000000', NULL, 1),
(4197273, 604829, 74979, '<td valign="top">this image, we can all relate to  having seen them all week on the news.. <br/> <br/>for me you lost impact by better focus on &amp; having the news truck share the frame equally with the fire''s victims;  w/o your title I would not get the impression these folks were troubled</td>', 'this image, we can all relate to  having seen them all week on the news..  for me you lost impact by better focus on & having the news truck share the frame equally with the fire''s victims;  w/o your title I would not get the impression these folks were troubled', '2007-10-26 11:41:47.000000', NULL, 1),
(4197275, 604694, 74979, '<td valign="top">clever image!</td>', 'clever image!', '2007-10-26 11:42:06.000000', NULL, 1),
(4197280, 604779, 74979, '<td valign="top">how odd is that??!!</td>', 'how odd is that??!!', '2007-10-26 11:45:40.000000', NULL, 1),
(4197295, 604801, 5822, '<td valign="top">Color seems off but bokeh is very nice.</td>', 'Color seems off but bokeh is very nice.', '2007-10-26 11:52:31.000000', NULL, 1),
(4197349, 603787, 11854, '<td valign="top">Awesome shot! He looks defeated. 10</td>', 'Awesome shot! He looks defeated. 10', '2007-10-26 12:26:39.000000', NULL, 1),
(4197353, 604140, 11854, '<td valign="top">Well done! 10</td>', 'Well done! 10', '2007-10-26 12:27:16.000000', NULL, 1),
(4197402, 604831, 68035, '<td valign="top">Very strong in terms of a newspaper image, this tells a story (albeit a sad one).  From my own perspective there is a bit of blow out on some of the flesh tones (although I appreciate that given this is minimal editing there is little that can be done about correcting this.  Still a strong image and gets an evocative 8 from me</td>', 'Very strong in terms of a newspaper image, this tells a story (albeit a sad one).  From my own perspective there is a bit of blow out on some of the flesh tones (although I appreciate that given this is minimal editing there is little that can be done about correcting this.  Still a strong image and gets an evocative 8 from me', '2007-10-26 12:53:59.000000', NULL, 1),
(4197403, 604698, 68035, '<td valign="top">Very good capture for the competition and one image that I could really imagine being in a newspaper.  I have to say from my own personal perspective I am glad you did not go for the closer shot<br/> <br/>Good job - 8</td>', 'Very good capture for the competition and one image that I could really imagine being in a newspaper.  I have to say from my own personal perspective I am glad you did not go for the closer shot Good job - 8', '2007-10-26 12:56:02.000000', NULL, 1),
(4197406, 604306, 68035, '<td valign="top">Verry good image for the challenge.  I might have prefered a punchier ''tabloid-esque'' title (Not that that affects my mark).  Nice symettry in the shot<br/> <br/>Good job</td>', 'Verry good image for the challenge.  I might have prefered a punchier ''tabloid-esque'' title (Not that that affects my mark).  Nice symettry in the shot Good job', '2007-10-26 12:57:45.000000', NULL, 1),
(4197409, 604481, 68035, '<td valign="top">Great smiles and moment of triumph capture.  The tight centred focus brings out the key subject very well although (from my own taste only) I might have prefered either a tighter crop when you shot the picture (appreciating that you could not change this afterwards)</td>', 'Great smiles and moment of triumph capture.  The tight centred focus brings out the key subject very well although (from my own taste only) I might have prefered either a tighter crop when you shot the picture (appreciating that you could not change this afterwards)', '2007-10-26 12:59:39.000000', NULL, 1),
(4197413, 604094, 68035, '<td valign="top">Great image, perhaps would more suit a feature in a journal rather than a front page but undoubtedly an image which I wish I could have taken.  Great shot</td>', 'Great image, perhaps would more suit a feature in a journal rather than a front page but undoubtedly an image which I wish I could have taken.  Great shot', '2007-10-26 13:01:18.000000', NULL, 1),
(4197415, 604831, 47906, '<td valign="top">This is a really touching image, the placement of the person really gives this one depth. Excellent image.</td>', 'This is a really touching image, the placement of the person really gives this one depth. Excellent image.', '2007-10-26 13:01:43.000000', NULL, 1),
(4197419, 604449, 68035, '<td valign="top">Very nice sports action capture that would grace any sports section of a paper.  Superb given its minimal editing</td>', 'Very nice sports action capture that would grace any sports section of a paper.  Superb given its minimal editing', '2007-10-26 13:02:33.000000', NULL, 1),
(4197420, 604636, 47906, '<td valign="top">I like the motion of the people in the foreground, I think your did good to isolation your subject well like this.</td>', 'I like the motion of the people in the foreground, I think your did good to isolation your subject well like this.', '2007-10-26 13:02:33.000000', NULL, 1),
(4197422, 604549, 47906, '<td valign="top">Nicely Light, Good Perspective. Should do well.</td>', 'Nicely Light, Good Perspective. Should do well.', '2007-10-26 13:03:06.000000', NULL, 1),
(4197424, 604387, 68035, '<td valign="top">Shocking image and definitely front page material.  Great composition and very evocative - 8</td>', 'Shocking image and definitely front page material.  Great composition and very evocative - 8', '2007-10-26 13:03:28.000000', NULL, 1),
(4197427, 604357, 47906, '<td valign="top">A bit small, you may want to change you DOF to create a more dramatic composition. Nice color and clarity.</td>', 'A bit small, you may want to change you DOF to create a more dramatic composition. Nice color and clarity.', '2007-10-26 13:04:06.000000', NULL, 1),
