INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4200568, 602453, 82707, '<td valign="top">Tells the story clearly! Nice shot!</td>', 'Tells the story clearly! Nice shot!', '2007-10-28 00:44:24.000000', NULL, 1),
(4200569, 604449, 82707, '<td valign="top">Ouch!  Nice shot!</td>', 'Ouch!  Nice shot!', '2007-10-28 00:44:27.000000', NULL, 1),
(4200570, 602409, 82707, '<td valign="top">What a lovely shot of a fun moment!</td>', 'What a lovely shot of a fun moment!', '2007-10-28 00:44:31.000000', NULL, 1),
(4200571, 604549, 82707, '<td valign="top">Interesting shot, nicely lit to show detail.  IMO the tree behind his right arm detracts a little from the sand details.</td>', 'Interesting shot, nicely lit to show detail.  IMO the tree behind his right arm detracts a little from the sand details.', '2007-10-28 00:44:35.000000', NULL, 1),
(4200572, 604593, 82707, '<td valign="top">Tells a dirty story.  Good composition.</td>', 'Tells a dirty story.  Good composition.', '2007-10-28 00:44:38.000000', NULL, 1),
(4200573, 604642, 82707, '<td valign="top">Yep they''re all smiling! Nice shot!</td>', 'Yep they''re all smiling! Nice shot!', '2007-10-28 00:44:41.000000', NULL, 1),
(4200576, 604306, 82707, '<td valign="top">Oh! Bugger!  I sincerely hope this is not your driveway. Picture certainly tells a story.  Congrats on a good image.</td>', 'Oh! Bugger!  I sincerely hope this is not your driveway. Picture certainly tells a story.  Congrats on a good image.', '2007-10-28 00:45:05.000000', NULL, 1),
(4200577, 603875, 82707, '<td valign="top">Unusual subject...nice group portrait...minimal editing doesn''t give you many options for the background of a period shot.</td>', 'Unusual subject...nice group portrait...minimal editing doesn''t give you many options for the background of a period shot.', '2007-10-28 00:45:12.000000', NULL, 1),
(4200581, 603294, 82707, '<td valign="top">A nice action shot.  I like the sharpness of the three players in the foreground.  It makes them stand out.  Nice composition.</td>', 'A nice action shot.  I like the sharpness of the three players in the foreground.  It makes them stand out.  Nice composition.', '2007-10-28 00:45:26.000000', NULL, 1),
(4200582, 604575, 82707, '<td valign="top">A little spooky, but technically very good.  Great lighting and lots of points of interest.</td>', 'A little spooky, but technically very good.  Great lighting and lots of points of interest.', '2007-10-28 00:45:39.000000', NULL, 1),
(4200584, 604548, 82707, '<td valign="top">Let''s hope that Holloween is soon!  I like the subject!  Nicely captured.</td>', 'Let''s hope that Holloween is soon!  I like the subject!  Nicely captured.', '2007-10-28 00:45:43.000000', NULL, 1),
(4200585, 604742, 82707, '<td valign="top">Technically a very nice photo, great lighting, lovely composition, but topic feels a little contrived.</td>', 'Technically a very nice photo, great lighting, lovely composition, but topic feels a little contrived.', '2007-10-28 00:45:49.000000', NULL, 1),
(4200587, 604140, 82707, '<td valign="top">Nice composition and colours, but I would have preferred that you cut out the red bit on the right, as it is a significant distraction from an otherwise appealling shot.  I know, Minimalist Editing Challenge, pretty tough!</td>', 'Nice composition and colours, but I would have preferred that you cut out the red bit on the right, as it is a significant distraction from an otherwise appealling shot.  I know, Minimalist Editing Challenge, pretty tough!', '2007-10-28 00:45:59.000000', NULL, 1),
(4200588, 604798, 82707, '<td valign="top">Lovely in B&amp;W.</td>', 'Lovely in B&W.', '2007-10-28 00:46:04.000000', NULL, 1),
(4200590, 604698, 82707, '<td valign="top">IMO a much tighter crop would have helped the image, but then I realised that it is minimal editing.  Nice action capture!</td>', 'IMO a much tighter crop would have helped the image, but then I realised that it is minimal editing.  Nice action capture!', '2007-10-28 00:46:09.000000', NULL, 1),
(4200591, 604805, 82707, '<td valign="top">You had my interest, but then it looks like a controlled burn with the individual fires, so doesn''t quite live up to the title.  Apologies if I am wrong.  Technically a nice image though.</td>', 'You had my interest, but then it looks like a controlled burn with the individual fires, so doesn''t quite live up to the title.  Apologies if I am wrong.  Technically a nice image though.', '2007-10-28 00:46:20.000000', NULL, 1),
(4200592, 604710, 75034, '<td valign="top">It is titilatting title for this topic. Nice headline to bad you could''t clone in about 80-100 more of them.</td>', 'It is titilatting title for this topic. Nice headline to bad you could''t clone in about 80-100 more of them.', '2007-10-28 00:46:24.000000', NULL, 1),
(4200593, 604094, 82707, '<td valign="top">One of the more interesting images in this challenge.  I love the use of fisheye lense, and the title.  I think it is technically very good.  Good lighting, interesting subject.</td>', 'One of the more interesting images in this challenge.  I love the use of fisheye lense, and the title.  I think it is technically very good.  Good lighting, interesting subject.', '2007-10-28 00:46:33.000000', NULL, 1),
(4200596, 603843, 82707, '<td valign="top">Such a topical subject!  IMO I would have preferred a tighter crop. I like the fog just beyond the fence.  It gives the image some additional character.</td>', 'Such a topical subject!  IMO I would have preferred a tighter crop. I like the fog just beyond the fence.  It gives the image some additional character.', '2007-10-28 00:47:18.000000', NULL, 1),
(4200597, 604007, 82707, '<td valign="top">Hope they raised lots of money.  Nice in B&amp;w!</td>', 'Hope they raised lots of money.  Nice in B&w!', '2007-10-28 00:47:22.000000', NULL, 1),
(4200601, 604369, 82707, '<td valign="top">I so want to still believe in the tooth fairy, thank you for trying! Technically very good, but IMHO just a small tweak in contrast would improve the image.  Great models!</td>', 'I so want to still believe in the tooth fairy, thank you for trying! Technically very good, but IMHO just a small tweak in contrast would improve the image.  Great models!', '2007-10-28 00:48:18.000000', NULL, 1),
(4200604, 604158, 82707, '<td valign="top">You can never go wrong with face paint and bubbles!  Nice image.</td>', 'You can never go wrong with face paint and bubbles!  Nice image.', '2007-10-28 00:48:46.000000', NULL, 1),
(4200606, 604705, 82707, '<td valign="top">Love the topic, but details of the subject are a little lost in a busy image.  I know! "Minimal Editing"!</td>', 'Love the topic, but details of the subject are a little lost in a busy image.  I know! "Minimal Editing"!', '2007-10-28 00:48:59.000000', NULL, 1),
(4200607, 604395, 82707, '<td valign="top">Nice portrait, but I don''t have any understanding of the title.  Excellent lighting and nice image.</td>', 'Nice portrait, but I don''t have any understanding of the title.  Excellent lighting and nice image.', '2007-10-28 00:49:04.000000', NULL, 1),
(4200608, 604817, 82707, '<td valign="top">Colour and sharpness is great, but I would prefer to see the expression on at least one face....OK! I know minimalist editing is very restrictive, but IMO, without that expression it is a bit impersonal, and that stops it from telling the whole story, but it''s still a nice image.</td>', 'Colour and sharpness is great, but I would prefer to see the expression on at least one face....OK! I know minimalist editing is very restrictive, but IMO, without that expression it is a bit impersonal, and that stops it from telling the whole story, but it''s still a nice image.', '2007-10-28 00:49:22.000000', NULL, 1),
(4200611, 604816, 82707, '<td valign="top">Nice colours!</td>', 'Nice colours!', '2007-10-28 00:51:44.000000', NULL, 1),
(4200613, 604749, 82707, '<td valign="top">You have captured the detail in the work shop, but the carpenter is a little in the dark.  But, nice image!</td>', 'You have captured the detail in the work shop, but the carpenter is a little in the dark.  But, nice image!', '2007-10-28 00:52:08.000000', NULL, 1),
(4200614, 604118, 82707, '<td valign="top">Beautiful image, serene smile, lovely lighting.  Congrats on a nice capture!</td>', 'Beautiful image, serene smile, lovely lighting.  Congrats on a nice capture!', '2007-10-28 00:52:18.000000', NULL, 1),
(4200627, 604140, 18367, '<td valign="top">A stunning image.  You might have considered cropping the image to remove that red item on the left of the photo.  You also seem to have several sensor dust spots that you should deal with since they truly to detract from what is otherwise a very nice photo.</td>', 'A stunning image.  You might have considered cropping the image to remove that red item on the left of the photo.  You also seem to have several sensor dust spots that you should deal with since they truly to detract from what is otherwise a very nice photo.', '2007-10-28 01:05:42.000000', NULL, 1),
(4200628, 604140, 75034, '<td valign="top">Nice shot. The DoF is great nad the colours are wonderful. I would offer a few small things and I hope it helps. First the framing of the image, I know that this is straight out of the camera and in Jpeg and you had limited time because the chopper was moving, but the fence and the wind sock are a little distracting not because they are there but mainly because there is not enough of them to be important to the shot. If edit or time allowed you would crop them out or move back and make them more a part of the image because they could help to tell a little more of the story. The wind sock or fence might have the name of the rescue deployment centre or the hospital on it and fill in some of the details.<br/>Second thing the title "Mountain Rescue" it might catch you for a sec but it dosen''t hold you for long at all. When people go through the paper the headlines have about 0.5 of a sec to catch your attention and about the same to hold it. You need to punch it up a bit, something like "Family of four rescued after plane goes down do to fog" or "Three men plucked from fridged mountain lake after boat capsizes"<br/>So there you have it my take on your shot and I would like to see what you would''ve done with an advanced or expert edit on this.</td>', 'Nice shot. The DoF is great nad the colours are wonderful. I would offer a few small things and I hope it helps. First the framing of the image, I know that this is straight out of the camera and in Jpeg and you had limited time because the chopper was moving, but the fence and the wind sock are a little distracting not because they are there but mainly because there is not enough of them to be important to the shot. If edit or time allowed you would crop them out or move back and make them more a part of the image because they could help to tell a little more of the story. The wind sock or fence might have the name of the rescue deployment centre or the hospital on it and fill in some of the details.Second thing the title "Mountain Rescue" it might catch you for a sec but it dosen''t hold you for long at all. When people go through the paper the headlines have about 0.5 of a sec to catch your attention and about the same to hold it. You need to punch it up a bit, something like "Family of four rescued after plane goes down do to fog" or "Three men plucked from fridged mountain lake after boat capsizes"So there you have it my take on your shot and I would like to see what you would''ve done with an advanced or expert edit on this.', '2007-10-28 01:05:59.000000', NULL, 1),
(4200734, 604387, 33352, '<td valign="top">Excellent framing for this challenge and tells a good story....Bump 10</td>', 'Excellent framing for this challenge and tells a good story....Bump 10', '2007-10-28 01:56:15.000000', NULL, 1),
(4200870, 604779, 70177, '<td valign="top">that is disgusting, i thought that was a bundle of bannannas, but it looks like a bunch of hands or squid tenticles.  :P</td>', 'that is disgusting, i thought that was a bundle of bannannas, but it looks like a bunch of hands or squid tenticles.  :P', '2007-10-28 02:32:18.000000', NULL, 1),
