(4201027, 603875, 49109, '<td valign="top">IMO the wrong title, were gone for sth like "XXth annual meeting of XXX". Light from their back didn''t help the image, a fill flash might have made miracles.</td>', 'IMO the wrong title, were gone for sth like "XXth annual meeting of XXX". Light from their back didn''t help the image, a fill flash might have made miracles.', '2007-10-28 07:57:12.000000', NULL, 1),
(4201029, 604140, 49109, '<td valign="top">good color and focus, had zoomed in a little closer to get rid of the fence and windbag.</td>', 'good color and focus, had zoomed in a little closer to get rid of the fence and windbag.', '2007-10-28 08:00:16.000000', NULL, 1),
(4201030, 604779, 49109, '<td valign="top">crop (no pun intended) is way too loose. the brown thing at right distracts. don''t eat that fruit!</td>', 'crop (no pun intended) is way too loose. the brown thing at right distracts. don''t eat that fruit!', '2007-10-28 08:00:53.000000', NULL, 1),
