(4203559, 603787, 74559, '<td valign="top">Very powerful image, both photographically and emotionally. Wonderful (scary) capture of fire; fantastic pov with the dark vortex by the brave fireman''s head, as if he is willing the fire to be extinguished ... this to me is photojournalism at its (painful) best!</td>', 'Very powerful image, both photographically and emotionally. Wonderful (scary) capture of fire; fantastic pov with the dark vortex by the brave fireman''s head, as if he is willing the fire to be extinguished ... this to me is photojournalism at its (painful) best!', '2007-10-29 12:41:26.000000', NULL, 1),
(4203738, 604158, 84239, '<td valign="top">I would have really loved this without the dark shaddows on her face and the colors to be a little more saturated. Pretty good though. 5</td>', 'I would have really loved this without the dark shaddows on her face and the colors to be a little more saturated. Pretty good though. 5', '2007-10-29 13:43:13.000000', NULL, 1),
(4203747, 604187, 84239, '<td valign="top">I think this would have worked better in B&amp;W. I think it would have brought the saddness out a little more. This way, with all the colors it is cofusing cause all the colors are bright and cheery and the message is not. Not bad though</td>', 'I think this would have worked better in B&W. I think it would have brought the saddness out a little more. This way, with all the colors it is cofusing cause all the colors are bright and cheery and the message is not. Not bad though', '2007-10-29 13:48:49.000000', NULL, 1),
(4203753, 602939, 173, '<td valign="top">Great shot! I think this one would look good in both B&amp;W and color.</td>', 'Great shot! I think this one would look good in both B&W and color.', '2007-10-29 13:52:40.000000', NULL, 1),
